// Copies the project's iOS app icons (src-tauri/icons/ios/) over the
// placeholder icons generated by `tauri ios init` in
// src-tauri/gen/apple/Assets.xcassets/AppIcon.appiconset/.
//
// Mirrors scripts/sync-android-resources.mjs: runs from
// tauri.ios.conf.json's beforeDevCommand/beforeBuildCommand, i.e. after
// `tauri ios init` and before the Xcode build. Fails loudly if gen/apple
// does not exist yet (run `npm run tauri -- ios init` first).

import { cpSync, existsSync } from "node:fs";

const source = new URL("../src-tauri/icons/ios/", import.meta.url);
const destination = new URL(
  "../src-tauri/gen/apple/Assets.xcassets/AppIcon.appiconset/",
  import.meta.url,
);

if (!existsSync(destination)) {
  throw new Error(
    "iOS project not initialized: AppIcon.appiconset not found under src-tauri/gen/apple. " +
      "Run `npm run tauri -- ios init` first.",
  );
}

cpSync(source, destination, { recursive: true });
